import{_ as l,r as e,o as i,c as r,e as t,a as n,s as o,d as a}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Controllers - October CMS - 3.x","titleTemplate":false,"description":"Create pages that implement various features like forms and lists.","frontmatter":{"subtitle":"Create pages that implement various features like forms and lists."},"headers":[{"level":3,"title":"Class Definition","slug":"class-definition","link":"#class-definition","children":[]},{"level":3,"title":"Controller Properties","slug":"controller-properties","link":"#controller-properties","children":[]},{"level":2,"title":"Initialization Logic","slug":"initialization-logic","link":"#initialization-logic","children":[]},{"level":2,"title":"Actions, Views and Routing","slug":"actions-views-and-routing","link":"#actions-views-and-routing","children":[]},{"level":2,"title":"Passing Data to Views","slug":"passing-data-to-views","link":"#passing-data-to-views","children":[]},{"level":2,"title":"Setting the Navigation Context","slug":"setting-the-navigation-context","link":"#setting-the-navigation-context","children":[]},{"level":2,"title":"Overriding a Response","slug":"overriding-a-response","link":"#overriding-a-response","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"3.x/extend/system/controllers.md","filePath":"3.x/extend/system/controllers.md"}'),u={name:"3.x/extend/system/controllers.md"};function d(g,s,h,k,m,f){const p=e("pre-heading"),c=e("post-heading");return i(),r("div",null,[t(p),s[0]||(s[0]=n("h1",null,"Controllers",-1)),t(c),s[1]||(s[1]=o(`<p>The October CMS backend implements an Model-View-Controller (MVC) pattern. This article describes how to develop backend controllers and how to configure controller behaviors.</p><p>Each controller is represented with a PHP script which resides in the the <strong>/controllers</strong> subdirectory of a Plugin directory. Controller views are <code>.php</code> files that reside in the controller view directory. The controller view directory name matches the controller class name written in lowercase. The view directory can also contain controller configuration files. An example of a controller directory structure:</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           ├── <code>controllers</code>
|           |   ├── users  <em>← View Directory</em>
|           |   |   ├── config_form.yaml  <em>← Config File</em>
|           |   |   ├── _partial.php  <em>← Partial File</em>
|           |   |   └── index.php  <em>← View File</em>
|           |   └── Users.php  <em>← Controller Class</em>
|           └── Plugin.php</p>
</code></pre>`,3)),s[2]||(s[2]=n("div",{class:"custom-block tip"},[n("p",null,[a("For a practical example of using backend controllers, check out the "),n("a",{href:"https://octobercms.com/support/article/ob-19",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Beyond Behaviors tutorial series"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a(".")])],-1)),s[3]||(s[3]=o(`<h3 id="class-definition"><a href="#class-definition" class="header-anchor">#</a> Class Definition</h3><p>The <code>create:controller</code> command generates a controller, configuration and view files. The first argument specifies the author and plugin name. The second argument specifies the controller class name.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:controller Acme.Blog Posts
</code></pre></div><p>Controller classes must extend the <code>Backend\\Classes\\Controller</code> class. As any other plugin class, controllers should belong to the <a href="./../system/plugins.html">plugin namespace</a>. The most basic representation of a Controller used inside a Plugin looks like this.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Posts</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span>    <span class="token comment">// ← Action method</span>
    <span class="token punctuation">{</span>

    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Usually each controller implements functionality for working with a single type of data - like blog posts or categories. All backend behaviors described below assume this convention.</p><h3 id="controller-properties"><a href="#controller-properties" class="header-anchor">#</a> Controller Properties</h3><p>The backend controller base class defines a number of properties that allow to configure the page appearance and manage the page security:</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>$fatalError</strong></td><td>allows to store a fatal exception generated in an action method in order to display it in the view.</td></tr><tr><td><strong>$user</strong></td><td>contains a reference to the the backend user object.</td></tr><tr><td><strong>$suppressView</strong></td><td>allows to prevent the view display. Can be updated in the action method or in the controller constructor.</td></tr><tr><td><strong>$params</strong></td><td>an array of the routed parameters.</td></tr><tr><td><strong>$action</strong></td><td>a name of the action method being executed in the current request.</td></tr><tr><td><strong>$publicActions</strong></td><td>defines an array of actions available without the backend user authentication. Can be overridden in the class definition.</td></tr><tr><td><strong>$requiredPermissions</strong></td><td>permissions required to view this page. Can be set in the class definition or in the controller constructor. See <a href="./../backend/users.html">users &amp; permissions</a> for details.</td></tr><tr><td><strong>$pageTitle</strong></td><td>sets the page title. Can be set in the action method.</td></tr><tr><td><strong>$bodyClass</strong></td><td>body class property used for customizing the layout. Can be set in the controller constructor or action method.</td></tr><tr><td><strong>$guarded</strong></td><td>controller specific methods which cannot be called as actions. Can be extended in the controller constructor.</td></tr><tr><td><strong>$layout</strong></td><td>specify a custom layout for the <a href="./../system/views.html">controller views</a>.</td></tr></tbody></table></div><h2 id="initialization-logic"><a href="#initialization-logic" class="header-anchor">#</a> Initialization Logic</h2><p>Controllers may perform initialization logic in the native <code>__construct</code> method.</p><div class="custom-block warning"><p>Logic inside the constructor is not protected and should not handle any sensitive logic.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div></div><p>The <code>beforeDisplay</code> method is called after the permission checks happen and most logic should be placed here. This includes initializing widgets and other shared components.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeDisplay</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Initialize widgets, handle file uploads, etc.</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="actions-views-and-routing"><a href="#actions-views-and-routing" class="header-anchor">#</a> Actions, Views and Routing</h2><p>Public controller methods, called <strong>actions</strong> are coupled to <strong>view files</strong> which represent the page corresponding the action. Backend view files use PHP syntax. Example of the <strong>index.php</strong> view file contents, corresponding to the <code>index</code> action method.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello World<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>URL of this page is made up of the author name, plugin name, controller name and action name.</p><div class="language-text extra-class"><pre class="language-text"><code>admin/[author name]/[plugin name]/[controller name]/[action name]
</code></pre></div><p>For example, the class definition used at the beginning of this article is accessible via the following URL.</p><div class="language-text extra-class"><pre class="language-text"><code>https://example.tld/admin/acme/blog/users/index
</code></pre></div><p>If a <a href="./plugins.html">plugin is registered</a> with a <strong>hint</strong> in the <code>pluginDetails</code> method, a shorter URL structure becomes available, which is useful for masking the author name in URLs.</p><div class="language-text extra-class"><pre class="language-text"><code>admin/[plugin hint]/[controller name]/[action name]
</code></pre></div><h2 id="passing-data-to-views"><a href="#passing-data-to-views" class="header-anchor">#</a> Passing Data to Views</h2><p>Use the controller&#39;s <code>$vars</code> property to pass any data directly to your view:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;myVariable&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>The variables passed with the <code>$vars</code> property can now be accessed directly in your view:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>The variable value is <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$myVariable</span> <span class="token delimiter important">?&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="setting-the-navigation-context"><a href="#setting-the-navigation-context" class="header-anchor">#</a> Setting the Navigation Context</h2><p>Plugins can register the backend navigation menus and submenus in the <a href="./../backend/navigation.html">plugin registration file</a>. The navigation context determines what backend menu and submenu are active for the current backend page. You can set the navigation context with the <code>BackendMenu</code> class:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">BackendMenu</span><span class="token operator">::</span><span class="token function">setContext</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The first parameter specifies the author and plugin names. The second parameter sets the menu code. The optional third parameter specifies the submenu code. Usually you call the <code>BackendMenu::setContext</code> in the controller constructor.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span> <span class="token punctuation">{</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">BackendMenu</span><span class="token operator">::</span><span class="token function">setContext</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You can set the title of the backend page with the <code>$pageTitle</code> property of the controller class (note that the form and list behaviors can do it for you):</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">pageTitle</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Blog Categories&#39;</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="overriding-a-response"><a href="#overriding-a-response" class="header-anchor">#</a> Overriding a Response</h2><p>You can override responses in your backend controllers as a mechanism for making changes to the response of a HTTP request. For example, you may wish to specify a HTTP header for certain actions in your controller, or redirect users if they don&#39;t meet certain criteria.</p><p>Overriding a response is useful particularly when extending other controllers. However you may find it useful to call these methods locally.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>SomeController</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">setResponseHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Test-Header&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Test&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If you want to check the routed action or parameters, you can find these available in the controller <code>getAction</code> and <code>getParams</code> methods.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context">Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>SomeController</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">getAction</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;index&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Only do it for the index action</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">getParams</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">??</span> <span class="token constant">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Only if first parameter exists</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To add a header to your response, you may call the <code>setResponseHeader</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setResponseHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Test-Header&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Test&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To change the status code of a response, use the <code>setStatusCode</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setStatusCode</span><span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To override the entire response, call the <code>setResponse</code> method, this will force the response regardless of what happens on the page&#39;s life cycle.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setResponse</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Page Not Found&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also pass a <code>Response</code> object to this method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setResponse</span><span class="token punctuation">(</span><span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>View the <a href="./../services/response-view.html">Views &amp; Responses article</a> for more information on building responses.</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../services/response-view.html">Views and Responses</a></li></ul></div>`,52))])}const y=l(u,[["render",d]]);export{b as __pageData,y as default};
